package com.trough.hot;
import android.os.*;import android.view.MotionEvent;import java.io.File;import org.json.*;
/** Bounded native controls for optional physical spacing; no injected poses. */
final class HalfSwordSpacingCheck implements Runnable {
 final boolean relax;double standingZ,fallenZ,recoveredZ;boolean independent;
 final HalfSwordView v;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();int stage,steps;double initial,approached,near,retreated,offX,offY,offDrift,tx,ty;boolean complete;
 HalfSwordSpacingCheck(HalfSwordView view){this(view,false);}HalfSwordSpacingCheck(HalfSwordView view,boolean ragdoll){relax=ragdoll;v=view;input=new HalfSwordAimCheck(v);}void start(){ui.postDelayed(this,150);}void need(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 double distance()throws Exception{JSONArray p=input.observation().getJSONArray("pelvis_cm");return Math.hypot(v.opponentRootX-p.getDouble(0),v.opponentRootY-p.getDouble(1));}
 void follow(boolean enabled)throws Exception{if(v.opponentFollow!=enabled)input.click("Opponent spacing · prototype");need(v.opponentFollow==enabled,"Spacing switch rejected");}
 public void run(){try{need(SystemClock.uptimeMillis()-began<25000,"Spacing timeout");need(v.renderVisible&&!v.characterFailed,"Scene unavailable");switch(stage){
 case 0:if(v.characterRunning)input.click("Run / pause");follow(false);input.click("Reset physics");input.click("Stance support setup");stage=1;break;
 case 1:if(v.resetPending())break;input.click("Run / pause");steps=v.characterSteps;stage=2;break;
 case 2:if(v.characterSteps-steps<60)break;need(v.passiveActive,"Opponent absent");if(relax){standingZ=v.opponentRootZ;input.click("Run / pause");input.pausedSteps=-1;stage=20;break;}initial=distance();follow(true);steps=v.characterSteps;stage=3;break;
 case 3:if(v.characterSteps-steps<180)break;approached=distance();need(initial-approached>10&&approached>=105&&approached<=150,"Opponent did not approach spacing band");follow(false);steps=v.characterSteps;stage=4;break;
 case 4:if(v.characterSteps-steps<60)break;offX=v.opponentRootX;offY=v.opponentRootY;steps=v.characterSteps;stage=5;break;
 case 5:if(v.characterSteps-steps<60)break;offDrift=Math.hypot(v.opponentRootX-offX,v.opponentRootY-offY);need(offDrift<3,"Disabled opponent did not brake");{JSONArray p=input.observation().getJSONArray("pelvis_cm");double dx=p.getDouble(0)-v.opponentRootX,dy=p.getDouble(1)-v.opponentRootY,l=Math.hypot(dx,dy);need(l>20,"Near setup invalid");tx=v.opponentRootX+dx/l*80;ty=v.opponentRootY+dy/l*80;}body(true);steps=v.characterSteps;stage=6;break;
 case 6:{JSONArray p=input.observation().getJSONArray("pelvis_cm");double remaining=Math.hypot(tx-p.getDouble(0),ty-p.getDouble(1));if(remaining>5&&v.characterSteps-steps<120){body(false);break;}need(remaining<15,"Near movement missed");}v.cancelAllTouchInputs();steps=v.characterSteps;stage=7;break;
 case 7:if(v.characterSteps-steps<60)break;near=distance();need(near<105&&near>40,"Near distance outside retreat sample");follow(true);steps=v.characterSteps;stage=8;break;
 case 8:if(v.characterSteps-steps<180)break;retreated=distance();need(retreated-near>10&&retreated>=105&&retreated<=155,"Opponent did not retreat");follow(false);steps=v.characterSteps;stage=9;break;
 case 9:if(v.characterSteps-steps<60)break;input.click("Run / pause");v.cancelAllTouchInputs();input.pausedSteps=-1;stage=10;break;
 case 20:if(!input.pausedScene(false))break;steps=v.characterSteps;input.click("Relax opponent");stage=21;break;
 case 21:if(v.characterBusy||!v.opponentRelaxApplied)break;need(v.characterSteps==steps+1&&!v.characterRunning&&!v.ragdollRelaxRequested&&!v.opponentFollow,"Opponent relax changed player/run state");independent=true;input.click("Run / pause");steps=v.characterSteps;stage=22;break;
 case 22:if(v.characterSteps-steps<90)break;fallenZ=v.opponentRootZ;need(Double.isFinite(fallenZ)&&fallenZ<standingZ-20,"Opponent did not fall");need(input.observation().getJSONArray("pelvis_cm").getDouble(2)>70&&!v.ragdollRelaxApplied,"Player lost support");input.click("Run / pause");input.pausedSteps=-1;stage=23;break;
 case 23:if(!input.pausedScene(true))break;{File base=new File(v.getContext().getFilesDir(),"home/.trough");try(java.io.FileInputStream in=new java.io.FileInputStream(new File(base,"half-sword-aim-held.png"));java.io.FileOutputStream out=new java.io.FileOutputStream(new File(base,"half-sword-opponent-fallen.png"))){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))>0)out.write(bytes,0,n);}}input.click("Reset physics");stage=24;break;
 case 24:if(v.resetPending())break;need(!v.opponentRelaxRequested&&!v.opponentRelaxApplied,"Reset retained opponent relax");input.click("Run / pause");steps=v.characterSteps;stage=25;break;
 case 25:if(v.characterSteps-steps<60)break;recoveredZ=v.opponentRootZ;need(recoveredZ>70&&v.passiveActive&&!v.opponentRelaxApplied,"Opponent did not recover");input.observation();input.click("Run / pause");input.pausedSteps=-1;stage=10;break;
 case 10:if(!input.pausedScene(true))break;complete=true;finish(null);return;
 }ui.postDelayed(this,50);}catch(Throwable e){v.characterRunning=false;v.opponentFollow=false;v.cancelAllTouchInputs();v.refreshRunControl();finish(e.toString());}}
 void body(boolean begin)throws Exception{JSONArray p=input.observation().getJSONArray("pelvis_cm");double dx=tx-p.getDouble(0),dy=ty-p.getDouble(1),l=Math.hypot(dx,dy),c=Math.cos(v.yaw),s=Math.sin(v.yaw),strength=.2+.8*Math.min(1,l/30);need(l>0,"Movement direction zero");HalfSwordBodyPushPad pad=v.bodyPushPad;float radius=Math.min(pad.getWidth(),pad.getHeight())*.4f;long now=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(now,now,begin?MotionEvent.ACTION_DOWN:MotionEvent.ACTION_MOVE,(float)(pad.getWidth()*.5+(dx*c+dy*s)/l*strength*radius),(float)(pad.getHeight()*.5-(-dx*s+dy*c)/l*strength*radius),0);try{need(pad.dispatchTouchEvent(e),"Movement input rejected");}finally{e.recycle();}}
 void finish(String error){try{JSONObject o=new JSONObject().put("passed",complete&&error==null).put("error",error==null?"":error).put("opponent_ragdoll",relax).put("independent_player_state",independent).put("standing_opponent_z_cm",standingZ).put("fallen_opponent_z_cm",fallenZ).put("recovered_opponent_z_cm",recoveredZ).put("initial_distance_cm",initial).put("approached_distance_cm",approached).put("disabled_drift_cm",offDrift).put("near_distance_cm",near).put("retreated_distance_cm",retreated).put("spacing_final_enabled",v.opponentFollow).put("steps",v.characterSteps).put("performance",v.performance()).put("module",HalfSwordBridge.loadedModuleSha256).put("time_ms",System.currentTimeMillis()).put("scope",relax?"Native independent opponent Relax/fall/Reset; player remains supported; no damage/death claim":"Native switch and bodypad; physical spacing prototype, not combat AI");Payloads.writeSmall(new File(v.getContext().getFilesDir(),"home/.trough/half-sword-spacing-check-result.json"),o.toString());}catch(Exception ignored){}}
}
